import{c as t,Q as a,j as n,m as r}from"./chunks/framework.BqPkuuVc.js";const o="/assets/docs-run-core-download-reader-bt-connect.B5MQl5ex.png",d="/assets/docs-reader-bt-picker-scanning.aOBIJ0k-.png",s="/assets/docs-reader-bt-picker-found.DSBovnbb.png",i="/assets/docs-run-core-download-panel-listening.DMA5TLPt.png",w=JSON.parse('{"title":"Downloading cards with a Reader BT","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/reader-bt.md","filePath":"user/running-the-event/reader-bt.md"}'),h={name:"user/running-the-event/reader-bt.md"};function c(l,e,g,p,m,u){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="downloading-cards-with-a-reader-bt" tabindex="-1">Downloading cards with a Reader BT <a class="header-anchor" href="#downloading-cards-with-a-reader-bt" aria-label="Permalink to &quot;Downloading cards with a Reader BT&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators at the download desk.</p><p>The SPORTident <strong>Reader BT</strong> is a download station that connects over Bluetooth instead of a USB cable. Cards read on it are downloaded exactly as they are from a USB station: same result banner, same downloads table, same splits print. This page covers connecting it, and what it does that a USB station doesn&#39;t. For everything after the card is read, see <a href="./card-download">Downloading cards</a>.</p><h2 id="get-going" tabindex="-1">Get going <a class="header-anchor" href="#get-going" aria-label="Permalink to &quot;Get going&quot;">​</a></h2><ol><li><strong>Wake the reader</strong> by inserting any card. It stays visible for 20 seconds.</li><li><strong>Click Connect Reader BT</strong> on the Card downloads page or the dashboard&#39;s <strong>Download card</strong> tile, pick <strong>Reader BT</strong> and its serial number in the browser&#39;s list, and click <strong>Pair</strong>.</li><li><strong>Read cards.</strong> The panel says <strong>Listening</strong>. Insert each card; the reader beeps twice for a good result and four times when the competitor should come to the desk.</li></ol><p>That&#39;s all for a normal day. The rest of this page covers what you need first, each step in more detail, and what to do when something is off.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li><strong>Chrome or Edge</strong> on Windows, macOS, Linux or Android. Safari and Firefox can&#39;t use Bluetooth readers, and nor can any browser on an iPhone or iPad.</li><li><strong>A secure connection</strong>, the same as a USB reader needs: open Manager at <strong><a href="http://localhost" target="_blank" rel="noreferrer">http://localhost</a></strong> on the server itself, or over HTTPS from any other computer or tablet. See <a href="./../reference/https-and-certificates">HTTPS and certificates</a>.</li><li><strong>The reader in Readout mode</strong>, with firmware 2.0 or later. Both are set in SPORTident&#39;s <strong>Config App</strong> on a phone, not in Manager. A new reader comes in Readout mode.</li><li><strong>On a Mac:</strong> Chrome needs permission to use Bluetooth. If the list in step 2 stays empty, open <strong>System Settings → Privacy &amp; Security → Bluetooth</strong> and turn Chrome on.</li></ul><p>An Android tablet in Chrome is a complete download desk: it can&#39;t use a USB station, but it can use a Reader BT.</p><h2 id="connecting" tabindex="-1">Connecting <a class="header-anchor" href="#connecting" aria-label="Permalink to &quot;Connecting&quot;">​</a></h2><p>The Card downloads page offers <strong>Connect Reader BT</strong> under <strong>Connect USB reader</strong>. The dashboard&#39;s <strong>Download card</strong> tile shows the same two buttons.</p><p><img src="'+o+'" alt="The SportIdent panel on the Card downloads page, not yet connected: Connect USB reader, and Connect Reader BT below it"></p><p>Click <strong>Connect Reader BT</strong>. The browser opens its own list and starts scanning:</p><p><img src="'+d+'" alt="Chrome&#39;s pairing window, &quot;http://localhost:60977 wants to pair&quot;, still scanning with nothing found"></p><p>When the reader is awake it appears as <strong>Reader BT</strong> and its serial number. Select it and click <strong>Pair</strong>:</p><p><img src="'+s+'" alt="The same window with &quot;Reader BT 1000163 – Paired&quot; in the list and the Pair button enabled"></p><p>The chip at the top of the panel turns green and reads <strong>Listening</strong>:</p><p><img src="'+i+'" alt="The SportIdent panel connected to the Reader BT: a green Listening chip and the prompt Insert SportIdent card"></p><p><strong>What to do:</strong> nothing more. The reader stays connected as you move around Manager.</p><table tabindex="0"><thead><tr><th>You see</th><th>It means</th><th>What to do</th></tr></thead><tbody><tr><td>The list stays empty</td><td>The reader is asleep, or (on a Mac) Chrome has no Bluetooth permission</td><td>Insert a card to wake it, then wait a few seconds. On a Mac, check the permission above.</td></tr><tr><td><strong>Paired</strong> beside the reader&#39;s name</td><td>The browser remembers it from an earlier connection</td><td>Nothing — pick it as usual.</td></tr><tr><td><em>The Reader BT is not in Readout mode</em></td><td>It&#39;s set to Printout or Standalone, so it would never send a card</td><td>Set it to Readout in the Config App, then connect again.</td></tr><tr><td><em>That device is not a Reader BT…</em></td><td>Another device was picked, or the firmware is older than 2.0</td><td>Pick the Reader BT, or update it in the Config App.</td></tr></tbody></table><p><strong>Don&#39;t pair the reader in your computer&#39;s Bluetooth settings.</strong> Manager connects to it directly, and a pairing made in Windows&#39; or macOS&#39;s settings can stop that working. If you already did, remove it there and connect from Manager again.</p><h2 id="reading-cards-and-the-beeps" tabindex="-1">Reading cards and the beeps <a class="header-anchor" href="#reading-cards-and-the-beeps" aria-label="Permalink to &quot;Reading cards and the beeps&quot;">​</a></h2><p>Insert a card. The reader sends it to Manager the moment it&#39;s in, and the result banner appears as it does for any download.</p><p>The reader doesn&#39;t beep when it reads the card. It beeps once Manager has checked the result, so the beep tells the competitor something:</p><table tabindex="0"><thead><tr><th>Beeps</th><th>Result</th><th>What to do</th></tr></thead><tbody><tr><td><strong>Two</strong></td><td>OK, overtime, or a card already downloaded</td><td>Nothing — the competitor can go.</td></tr><tr><td><strong>Four</strong></td><td>Missing punch, did not finish, a card nobody is entered on, a card already used by someone who finished, not competing, or the download didn&#39;t reach the server</td><td>Ask the competitor to come to the desk, and deal with it from the result banner as usual.</td></tr></tbody></table><p>A USB station beeps only when a read works, so this is something only the Reader BT can do: send a competitor with a mis-punch to the desk before they walk off.</p><h2 id="when-something-goes-wrong" tabindex="-1">When something goes wrong <a class="header-anchor" href="#when-something-goes-wrong" aria-label="Permalink to &quot;When something goes wrong&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You see</th><th>It means</th><th>What to do</th></tr></thead><tbody><tr><td><em>The Reader BT disconnected…</em></td><td>It went out of range, or switched itself off</td><td>Insert a card to wake it, then click <strong>Connect Reader BT</strong> again. Cards already read are safe on the server.</td></tr><tr><td><em>The card could not be read over Bluetooth…</em> (shown briefly, with four beeps)</td><td>The card&#39;s data arrived damaged</td><td>Ask the competitor to insert the card again.</td></tr><tr><td>A card is inserted and nothing happens</td><td>The reader isn&#39;t connected to this computer</td><td>Check the chip says <strong>Listening</strong>; connect again if it doesn&#39;t.</td></tr></tbody></table><p>A refreshed or closed browser tab drops the connection, as it does for a USB reader. Click <strong>Connect Reader BT</strong> again; you won&#39;t need to pick the reader from scratch if the browser remembers it.</p><h2 id="using-a-reader-bt-and-a-usb-station-together" tabindex="-1">Using a Reader BT and a USB station together <a class="header-anchor" href="#using-a-reader-bt-and-a-usb-station-together" aria-label="Permalink to &quot;Using a Reader BT and a USB station together&quot;">​</a></h2><p>You can have both connected in the same browser. Cards from either are downloaded; the panel describes the Reader BT while it is connected.</p><h2 id="what-the-reader-bt-doesn-t-do-in-manager" tabindex="-1">What the Reader BT doesn&#39;t do in Manager <a class="header-anchor" href="#what-the-reader-bt-doesn-t-do-in-manager" aria-label="Permalink to &quot;What the Reader BT doesn&#39;t do in Manager&quot;">​</a></h2><ul><li><strong>Station memory.</strong> Manager can&#39;t read the Reader BT&#39;s backup memory. If you need it, read it with SPORTident&#39;s tools.</li><li><strong>Card numbers into a form.</strong> Clicking into a <strong>Card number</strong> box and inserting a card fills the number in from a USB station only.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./card-download">Downloading cards</a> — the result banner, the downloads table and fixing a result</li><li><a href="./../reference/https-and-certificates">HTTPS and certificates</a> — downloading on a computer other than the server</li><li><a href="./../reference/sportident-cards">SportIdent cards</a></li></ul>',35)])])}const f=t(h,[["render",c]]);export{w as __pageData,f as default};
